(2370339, 328187, 33672, '<td valign="top">The grey tones are very rich. Nice capture and comp.</td>', 'The grey tones are very rich. Nice capture and comp.', '2006-05-01 22:40:09.000000', NULL, 1),
(2370364, 328037, 33672, '<td valign="top">A little too dark but a nice comp and capture.</td>', 'A little too dark but a nice comp and capture.', '2006-05-01 22:50:03.000000', NULL, 1),
(2370366, 327588, 33672, '<td valign="top">Great colors and tones</td>', 'Great colors and tones', '2006-05-01 22:50:49.000000', NULL, 1),
(2370389, 328542, 3102, '<td valign="top">A nice enough pose, but the skin tones need some serious work, I''m afraid.  Everything is way too yellowish and contrasty.  Probably a little too much headroom there, too.</td>', 'A nice enough pose, but the skin tones need some serious work, I''m afraid.  Everything is way too yellowish and contrasty.  Probably a little too much headroom there, too.', '2006-05-01 22:58:47.000000', NULL, 1),
