(2370416, 327676, 37252, '<td valign="top">very nice - good lighting</td>', 'very nice - good lighting', '2006-05-01 23:10:07.000000', NULL, 1),
(2370418, 328191, 53147, '<td valign="top">I think this is a brilliant shot. The white on white works great. The composition is phenomenal. I love this alot. Well done and bumping way up.</td>', 'I think this is a brilliant shot. The white on white works great. The composition is phenomenal. I love this alot. Well done and bumping way up.', '2006-05-01 23:10:36.000000', NULL, 1),
(2370420, 328002, 53147, '<td valign="top">Great lines color and chrome. Great 50s feel. My only complaint (albeit a small one) is the stuff in the background. The loose cord is a distraction. Other than thta - wonderful shot. Bumping up.</td>', 'Great lines color and chrome. Great 50s feel. My only complaint (albeit a small one) is the stuff in the background. The loose cord is a distraction. Other than thta - wonderful shot. Bumping up.', '2006-05-01 23:12:16.000000', NULL, 1),
(2370422, 327889, 53147, '<td valign="top">Man I wish I had a store like this around my neighborhood. Great shot - cant help but have great colors. Reall well done. Bumping up.</td>', 'Man I wish I had a store like this around my neighborhood. Great shot - cant help but have great colors. Reall well done. Bumping up.', '2006-05-01 23:13:12.000000', NULL, 1),
