(2386376, 328531, 55782, '<td valign="top">i like this photo, but the sky seems overexposed.</td>', 'i like this photo, but the sky seems overexposed.', '2006-05-05 23:58:43.000000', NULL, 1),
(2386378, 327766, 55782, '<td valign="top">the bird, which is the focus of your shot is a bit out of focus.  the crop is a little off to me as well.</td>', 'the bird, which is the focus of your shot is a bit out of focus.  the crop is a little off to me as well.', '2006-05-05 23:59:35.000000', NULL, 1),
